<script setup lang="ts">
import {computed,onMounted,onScopeDispose,ref} from 'vue';
import { useDesignDocument } from '@/application/workspace/DocumentStore';
import { useCommerce } from '@/application/workspace/UseCommerce';
import { failureMessage,type AccessControls } from '@/application/workspace/UseAccess';
import type {WorkspaceControls} from '@/application/workspace/UseWorkspace';
import {useUiLocale} from '@/application/shared/UseUiLocale';
import {requestConfirmation,notifyError} from '@/application/shared/UseFeedback';
import ContentSkeleton from '@/presentation/shared/ContentSkeleton.vue';
import {catalogueLocales,productCopy,productEligibleForCatalogue,type CatalogueLocale,type CommerceDraft} from '@/domain/workspace/Commerce';
import {catalogueMetadata} from '@/domain/workspace/CatalogueDocuments';
import {cloneSnapshot,type CatalogueWebPage,type CatalogueMetadata,type CatalogueCopy,type CatalogueSettings} from '@/domain/workspace/EditorModels';
import {refreshCatalogue,catalogueSettings,catalogueMediaGroups,catalogueCopy,catalogueCopyFields} from '@/domain/workspace/CatalogueEditing';
import CatalogueWebPreview from './CatalogueWebPreview.vue';
import CataloguePublication from './CataloguePublication.vue';
import DesignRecovery from './DesignRecovery.vue';
defineOptions({name:'CatalogueWebDesigner'});
const props=defineProps<{access:AccessControls;workspace:WorkspaceControls;documentId:string}>();
const {t}=useUiLocale(),controller=new AbortController(),store=useDesignDocument(props.access,props.workspace.organization.value!.id,'catalogue'),api=useCommerce(props.access);
const draft=ref<CommerceDraft|null>(null),loading=ref(true),selected=ref(''),viewport=ref(1440),previewAll=ref(false),publishing=ref(false);
const metadata=computed(()=>store.snapshot.value?catalogueMetadata(store.snapshot.value):null);
const copy=computed(()=>store.snapshot.value?catalogueCopy(store.snapshot.value):null);
const copyLabels:Record<keyof CatalogueCopy,string>={collection:'Collection heading',coverNote:'Cover note',header:'Page header',footer:'Page footer',sizes:'Sizes label',pieces:'Quantity unit',priceOnRequest:'Price on request',prices:'Prices heading',materials:'Fabric label',decoration:'Decoration label'};
const priceLabels:Record<keyof CatalogueSettings['priceDisplay'],string>={show:'Show price block',showCurrency:'Show currency',showQuantity:'Show quantity ranges',showRetail:'Show retail prices',showWholesale:'Show wholesale prices'};
function copyField(key:keyof CatalogueCopy,event:Event){if(locked.value||!store.snapshot.value||!copy.value)return;const next=cloneSnapshot(store.snapshot.value);next.catalogueSettings=catalogueSettings(next);next.catalogueSettings.copyByLocale[next.locale]={...copy.value,[key]:(event.target as HTMLTextAreaElement).value};store.replace(refreshCatalogue(next,draft.value?[draft.value]:[]).snapshot);}
function priceField(key:keyof CatalogueSettings['priceDisplay'],event:Event){if(locked.value||!store.snapshot.value)return;const next=cloneSnapshot(store.snapshot.value);next.catalogueSettings=catalogueSettings(next);next.catalogueSettings.priceDisplay[key]=(event.target as HTMLInputElement).checked;store.replace(refreshCatalogue(next,draft.value?[draft.value]:[]).snapshot);}
const page=computed(()=>metadata.value?.web.pages.find(item=>item.id===selected.value));
const locked=computed(()=>!props.workspace.canEdit.value||store.busy.value||props.access.busy.value||publishing.value||loading.value);
const products=computed(()=>draft.value?.snapshot.products.filter(item=>item.document.status!=='archived')??[]);
const excluded=computed(()=>[...new Set(metadata.value?.web.pages.filter(page=>page.isActive).flatMap(page=>page.productIds.filter(id=>!products.value.some(product=>product.document.id===id&&productEligibleForCatalogue(product,store.snapshot.value!.locale))))??[])]);
onMounted(async()=>{try{if(await store.load(props.documentId)){selected.value=metadata.value?.web.pages[0]?.id??'';await loadProducts();}}finally{loading.value=false;}});onScopeDispose(()=>controller.abort());
async function loadProducts(){const brand=store.snapshot.value?.catalogueSettings?.brandId??props.workspace.brands.value?.[0]?.id;if(!brand)return;const result=await api.get(props.workspace.organization.value!.id,brand,controller.signal);if(result.ok)draft.value=result.value;else notifyError(failureMessage(result.failure));}
function change(update:(value:CatalogueMetadata)=>void){if(locked.value||!store.snapshot.value)return;const next=cloneSnapshot(store.snapshot.value);next.catalogue=catalogueMetadata(next);update(next.catalogue);store.replace(next);}
function editPage(patch:Partial<CatalogueWebPage>){change(value=>{const current=value.web.pages.find(item=>item.id===selected.value);if(current)Object.assign(current,patch);});}
function addPage(){const id=crypto.randomUUID();change(value=>value.web.pages.push({id,title:t('New page'),layout:'grid',isActive:true,productIds:[]}));selected.value=id;}
function duplicatePage(){if(!page.value)return;const copy={...page.value,id:crypto.randomUUID(),productIds:[...page.value.productIds]};change(value=>value.web.pages.splice(value.web.pages.findIndex(item=>item.id===selected.value)+1,0,copy));selected.value=copy.id;}
async function removePage(){if(!page.value||!metadata.value||!await requestConfirmation(t('Remove this page? You can undo this change.'),{confirmLabel:t('Remove page')}))return;change(value=>{value.web.pages=value.web.pages.filter(item=>item.id!==selected.value);});selected.value=metadata.value.web.pages[0]?.id??'';}
function movePage(direction:number){change(value=>{const index=value.web.pages.findIndex(item=>item.id===selected.value),to=index+direction;if(index<0||to<0||to>=value.web.pages.length)return;const [item]=value.web.pages.splice(index,1);value.web.pages.splice(to,0,item!);});}
function product(id:string){if(!page.value)return;editPage({productIds:page.value.productIds.includes(id)?page.value.productIds.filter(item=>item!==id):[...page.value.productIds,id]});}
function language(event:Event){if(!store.snapshot.value)return;store.replace(refreshCatalogue(store.snapshot.value,draft.value?[draft.value]:[],(event.target as HTMLSelectElement).value as CatalogueLocale).snapshot);}
function group(event:Event){if(!store.snapshot.value)return;const next=cloneSnapshot(store.snapshot.value);next.catalogueSettings=catalogueSettings(next);next.catalogueSettings.mediaGroup=(event.target as HTMLSelectElement).value as NonNullable<typeof next.catalogueSettings>['mediaGroup'];store.replace(next);}
async function refresh(){loading.value=true;try{await loadProducts();if(store.snapshot.value&&draft.value)store.replace(refreshCatalogue(store.snapshot.value,[draft.value]).snapshot);}finally{loading.value=false;}}
</script>
<template><ContentSkeleton v-if="loading&&!store.snapshot.value" :cards="3" :label="t('Loading catalogue designer')"/><section v-else-if="store.snapshot.value&&metadata" class="web-designer"><header><div><p class="eyebrow">{{t('Web designer')}}</p><input v-model="store.title.value" class="catalogue-title" :aria-label="t('Catalogue name')" :disabled="locked"><p>{{store.dirty.value?t('Unsaved changes'):t('Saved')}}</p></div><div class="actions"><button :disabled="locked||!store.history.value.length" @click="store.undo">{{t('Undo')}}</button><button :disabled="locked||!store.future.value.length" @click="store.redo">{{t('Redo')}}</button><button :disabled="locked||!store.dirty.value" @click="store.save()">{{t('Save catalogue')}}</button></div></header>
 <DesignRecovery :recovery="store.recovery" :disabled="locked"/>
 <p v-if="!metadata.outputs.web" class="notice">{{t('Web output is disabled. Enable it in catalogue settings.')}}</p>
 <div class="web-toolbar"><label>{{t('Catalogue language')}}<select :value="store.snapshot.value.locale" :disabled="locked" @change="language"><option v-for="locale in catalogueLocales" :key="locale.code" :value="locale.code">{{locale.name}}</option></select></label><label>{{t('Website style')}}<select :value="metadata.web.theme" :disabled="locked" @change="change(value=>value.web.theme=($event.target as HTMLSelectElement).value as 'editorial'|'grid')"><option value="editorial">{{t('Editorial')}}</option><option value="grid">{{t('Minimal grid')}}</option></select></label><label>{{t('Photo group')}}<select :value="store.snapshot.value.catalogueSettings?.mediaGroup??'all'" :disabled="locked" @change="group"><option v-for="value in catalogueMediaGroups" :key="value" :value="value">{{t(value)}}</option></select></label><button :disabled="locked" @click="refresh">{{t('Refresh products')}}</button></div>
 <details v-if="copy" class="shared-copy"><summary>{{t('Shared text and prices')}}</summary><fieldset :disabled="locked"><div class="copy-grid"><label v-for="key in catalogueCopyFields" :key="key">{{t(copyLabels[key])}}<textarea :value="copy[key]" rows="2" maxlength="1000" :lang="store.snapshot.value.locale" :dir="catalogueLocales.find(item=>item.code===store.snapshot.value!.locale)?.dir" @change="copyField(key,$event)" /></label></div><div class="actions"><label v-for="(label,key) in priceLabels" :key="key" class="check"><input type="checkbox" :checked="store.snapshot.value.catalogueSettings?.priceDisplay[key]??true" @change="priceField(key,$event)">{{t(label)}}</label></div><p>{{t('Names, materials and prices are edited in Products. Refresh brings saved values into this design.')}}</p></fieldset></details>
 <p v-if="excluded.length" class="notice">{{t('Products excluded from this language preview:')}} {{excluded.join(', ')}}. {{t('Approve translations and resolve product issues, or remove those products from the page.')}}</p>
 <div class="designer-grid"><aside><h2>{{t('Web pages')}}</h2><button v-for="item in metadata.web.pages" :key="item.id" class="page-choice" :class="{selected:item.id===selected}" @click="selected=item.id">{{item.title}} <span v-if="!item.isActive">· {{t('Inactive')}}</span></button><div class="actions"><button :disabled="locked||metadata.web.pages.length>=100" @click="addPage">{{t('Add page')}}</button><button :disabled="locked||!page" @click="duplicatePage">{{t('Duplicate')}}</button></div><fieldset v-if="page" :disabled="locked"><label>{{t('Page name')}}<input :value="page.title" maxlength="160" @change="editPage({title:($event.target as HTMLInputElement).value})"></label><label>{{t('Page template')}}<select :value="page.layout" @change="editPage({layout:($event.target as HTMLSelectElement).value as CatalogueWebPage['layout']})"><option value="spread">{{t('Product story')}}</option><option value="grid">{{t('Product grid')}}</option><option value="collage">{{t('Photo collage')}}</option></select></label><label class="check"><input type="checkbox" :checked="page.isActive" @change="editPage({isActive:($event.target as HTMLInputElement).checked})">{{t('Active page')}}</label><div class="actions"><button @click="movePage(-1)">{{t('Move up')}}</button><button @click="movePage(1)">{{t('Move down')}}</button><button @click="removePage">{{t('Remove page')}}</button></div><h3>{{t('Products on this page')}}</h3><label v-for="item in products" :key="item.document.id" class="check"><input type="checkbox" :checked="page.productIds.includes(item.document.id)" @change="product(item.document.id)"><span>{{productCopy(item,store.snapshot.value.locale).name||item.document.id}}<small v-if="!productEligibleForCatalogue(item,store.snapshot.value.locale)">{{t('Unavailable in this language')}}</small></span></label></fieldset></aside>
 <div class="preview-workspace"><div class="preview-toolbar"><button v-for="device in [{width:1440,label:'Desktop'},{width:768,label:'Tablet'},{width:390,label:'Mobile'}]" :key="device.width" :aria-pressed="viewport===device.width" @click="viewport=device.width">{{t(device.label)}}</button><label class="check"><input v-model="previewAll" type="checkbox">{{t('Preview all active pages')}}</label><span>{{viewport}} px</span></div><p v-if="page&&!page.isActive" class="notice">{{t('This page is inactive and will not be published.')}}</p><div class="preview-scroll"><div class="responsive-preview" :style="{width:viewport+'px'}"><CatalogueWebPreview :snapshot="store.snapshot.value" :title="store.title.value" :draft="draft" :organization-id="workspace.organization.value!.id" :page-id="previewAll?undefined:selected"/></div></div></div></div>
 <CataloguePublication :access="access" :workspace="workspace" :document="store.record.value" :dirty="store.dirty.value" :disabled="locked" @busy="publishing=$event"/>
 </section><p v-else>{{t('This catalogue is unavailable.')}}</p></template>
<style scoped>.web-designer{display:grid;gap:20px}.web-designer>header,.web-toolbar,.actions,.preview-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:space-between}.catalogue-title{font:30px Georgia,serif;background:transparent;border:0!important;max-width:600px}.web-toolbar{justify-content:start}label{display:grid;gap:6px;font-size:13px}button,input,select,textarea{font:inherit;padding:8px;border:1px solid var(--color-border,#ccc4b6);border-radius:5px;color:inherit;background:var(--color-card,#fffdf8)}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.copy-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:15px 0}.shared-copy{border:1px solid var(--color-border);padding:16px;border-radius:8px}.shared-copy summary{cursor:pointer}.designer-grid{display:grid;grid-template-columns:270px minmax(0,1fr);gap:22px}.designer-grid aside{border:1px solid var(--color-border,#d9d1c2);padding:16px;border-radius:10px;display:grid;align-content:start;gap:12px}.page-choice{text-align:left}.page-choice.selected{border-color:var(--color-primary,#756b50);background:var(--color-accent,#ede8da)}.check{display:flex;gap:8px;align-items:start}small{display:block;font-size:11px;opacity:.7}fieldset{border:0;padding:0;display:grid;gap:12px}h2,h3{font-size:16px;margin:10px 0}.preview-workspace{min-width:0}.preview-toolbar{margin-bottom:12px;justify-content:start}.preview-scroll{overflow:auto;max-height:78vh;background:var(--color-muted,#d9d6d0);padding:20px;border-radius:10px}.responsive-preview{min-height:600px;box-shadow:0 5px 30px #0002}.notice{padding:14px;background:var(--color-accent,#eee4c8);border:1px solid var(--color-border,#cdbf9e);color:var(--color-foreground,#584720);line-height:1.6;font-size:13px}@media(max-width:900px){.designer-grid{grid-template-columns:1fr}.designer-grid aside{max-height:450px;overflow:auto}.preview-scroll{padding:10px}.catalogue-title{max-width:85vw;font-size:26px}}</style>
